mapper.select:
select a.id as id, a.work_time as workTime, a.performance_state as performanceState, a.performance_state_name as performanceStateName, a.hr_id as hrId, a.hr_name as hrName, a.general_manager_id as generalManagerId,a.general_manager_time as generalManagerTime, a.general_manager_name as generalManagerName, a.query_password as queryPassword, a.reason as reason, a.hr_manage_id as hrManageId, a.hr_manage_name as hrManageName, organ.organManagerInfo as organManagerInfo, superior.superiorManagerInfo as superiorManagerInfo, firstSuperior.superiorManagerInfo as firstSuperiorManagerInfo from staff_performance a left join ( SELECT organManager.id as id, cast(GROUP_CONCAT(CONCAT(IFNULL(organManager.bName,''),'_',IFNULL(organManager.bState,''))) as char) as organManagerInfo from ( SELECT a.id,b.organ_manager_name as bName,b.state as bState,b.organ_manager_user_id as bUserId FROM staff_performance a left join staff_performance_manager b on a.id = b.staff_performance_id and b.manager_type = 1 where 1=1
and b.organ_manager_user_id = #{userId,jdbcType=BIGINT}
and b.superior_manager_user_id = #{userId,jdbcType=BIGINT}
and (b.superior_manager_user_id = #{userId,jdbcType=BIGINT} or b.organ_manager_user_id = #{userId,jdbcType=BIGINT})
and b.organ_manager_user_id = #{organManagerUserId,jdbcType=BIGINT} and b.superior_manager_user_id = #{superiorManagerUserId,jdbcType=BIGINT}
GROUP BY a.id,b.organ_manager_user_id ) organManager GROUP BY organManager.id ) organ on a.id = organ.id
left join ( SELECT organManager.id as id, cast(GROUP_CONCAT(CONCAT(IFNULL(organManager.bName,''),'_',IFNULL(organManager.bState,''))) as char) as superiorManagerInfo from ( SELECT a.id,b.superior_manager_name as bName,c.state as bState,b.superior_manager_user_id as bUserId FROM staff_performance a left join staff_performance_manager b on a.id = b.staff_performance_id and b.manager_type = 1 left join staff_performance_manager c on b.superior_manager_user_id = c.organ_manager_user_id and c.manager_type = 2 and a.id = c.staff_performance_id where 1=1
and b.organ_manager_user_id = #{userId,jdbcType=BIGINT}
and b.superior_manager_user_id = #{userId,jdbcType=BIGINT}
and (b.superior_manager_user_id = #{userId,jdbcType=BIGINT} or b.organ_manager_user_id = #{userId,jdbcType=BIGINT})
GROUP BY a.id,b.superior_manager_user_id ) organManager GROUP BY organManager.id ) superior on a.id = superior.id left join ( SELECT organManager.id as id, cast(GROUP_CONCAT(CONCAT(IFNULL(organManager.bName,''),'_',IFNULL(organManager.bState,''))) as char) as superiorManagerInfo from ( SELECT a.id,b.superior_manager_name as bName,c.state as bState,b.superior_manager_user_id as bUserId FROM staff_performance a left join staff_performance_manager b on a.id = b.staff_performance_id and b.manager_type = 1 left join staff_performance_manager c on b.superior_manager_user_id = c.organ_manager_user_id and c.manager_type = 3 and a.id = c.staff_performance_id where 1=1
and b.organ_manager_user_id = #{userId,jdbcType=BIGINT}
and b.superior_manager_user_id = #{userId,jdbcType=BIGINT}
and (b.superior_manager_user_id = #{userId,jdbcType=BIGINT} or b.organ_manager_user_id = #{userId,jdbcType=BIGINT})
GROUP BY a.id,b.superior_manager_user_id ) organManager GROUP BY organManager.id ) firstSuperior on a.id = firstSuperior.id
left join ( SELECT superiorManager.id as id, cast(GROUP_CONCAT(CONCAT(IFNULL(superiorManager.cName,''),'_',IFNULL(superiorManager.cState,''))) as char) as superiorManagerInfo from ( SELECT a.id,c.organ_manager_name as cName,c.state as cState,c.organ_manager_user_id as cUserId FROM staff_performance a left join staff_performance_manager c on a.id = c.staff_performance_id and c.manager_type = 2 where 1=1
and c.organ_manager_user_id = #{userId,jdbcType=BIGINT}
and c.superior_manager_user_id = #{userId,jdbcType=BIGINT}
and (c.superior_manager_user_id = #{userId,jdbcType=BIGINT} or c.organ_manager_user_id = #{userId,jdbcType=BIGINT})
and c.organ_manager_user_id = #{superiorManagerUserId,jdbcType=BIGINT}
GROUP BY a.id,c.organ_manager_user_id ) superiorManager GROUP BY superiorManager.id ) superior on a.id = superior.id
left join ( SELECT superiorManager.id as id, cast(GROUP_CONCAT(CONCAT(IFNULL(superiorManager.cName,''),'_',IFNULL(superiorManager.cState,''))) as char) as superiorManagerInfo from ( SELECT a.id,c.organ_manager_name as cName,c.state as cState,c.organ_manager_user_id as cUserId FROM staff_performance a left join staff_performance_manager c on a.id = c.staff_performance_id and c.manager_type = 3 where 1=1
and c.organ_manager_user_id = #{userId,jdbcType=BIGINT}
and c.superior_manager_user_id = #{userId,jdbcType=BIGINT}
and (c.superior_manager_user_id = #{userId,jdbcType=BIGINT} or c.organ_manager_user_id = #{userId,jdbcType=BIGINT})
and c.organ_manager_user_id = #{superiorManagerUserId,jdbcType=BIGINT}
GROUP BY a.id,c.organ_manager_user_id ) superiorManager GROUP BY superiorManager.id ) firstSuperior on a.id = firstSuperior.id
where a.delete_flag =0
order by a.update_time desc
limit #{pageIndex}, #{pageSize}
